import{_ as s,o as e,c as i,a2 as n}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"配置入门","description":"","frontmatter":{},"headers":[],"relativePath":"config/getting-started.md","filePath":"config/getting-started.md","lastUpdated":1791730262000}'),t={name:"config/getting-started.md"};function r(l,a,p,d,o,c){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="配置入门" tabindex="-1">配置入门 <a class="header-anchor" href="#配置入门" aria-label="Permalink to &quot;配置入门&quot;">​</a></h1><p>默认配置打进 APK，用户覆盖文件只需写要改变的键。参数在 ui.toml，文案在 zh-Hans.toml。用<a href="/LyraPlayer-docs-site/config/reference/">全部配置表</a>查当前字段，不从旧截图猜名称。</p><h2 id="文件位置" tabindex="-1">文件位置 <a class="header-anchor" href="#文件位置" aria-label="Permalink to &quot;文件位置&quot;">​</a></h2><p>宿主取 Android external files root，缺失时用 internal files root，再拼接 <code>lyra/config</code>。常见外部位置：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/storage/emulated/0/Android/data/com.petehsu.lyraplayer/files/lyra/config/</span></span>
<span class="line"><span>  ui.toml</span></span>
<span class="line"><span>  zh-Hans.toml</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>内部通常是 <code>/data/user/0/com.petehsu.lyraplayer/files/lyra/config/</code>。实际根由系统提供，存储卷和 Android 版本会改变访问方式。以日志 <code>config dir ...</code> 确认。普通文件管理器可能无权访问 Android/data，正式 APK 的 run-as 不保证可用。</p><p>每个文件优先读取外部非空覆盖，外部为空/不存在才读内部；不是把外部与内部逐键再叠加。覆盖在内置 defaults 之上，类型必须一致。</p><h2 id="改字号与交互" tabindex="-1">改字号与交互 <a class="header-anchor" href="#改字号与交互" aria-label="Permalink to &quot;改字号与交互&quot;">​</a></h2><p>创建或合并到用户 ui.toml：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">player</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lyric_main_mini_sp = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">22</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lyric_main_expanded_sp = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">36</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">progress_relative_drag = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这个文件不用复制其他数百个默认键。保留已有配置，避免一个示例覆盖用户其他设置。不要在同一文件重复 <code>[player]</code>/同一键，使用编辑器定位现有表修改。</p><h2 id="生效与恢复" tabindex="-1">生效与恢复 <a class="header-anchor" href="#生效与恢复" aria-label="Permalink to &quot;生效与恢复&quot;">​</a></h2><p>文件监听在安全帧边界请求重新加载；接口写入同样下一帧激活。无效类型/范围不应当作有效配置使用。启动可能使用安全默认回退，运行时失败保留可用状态；不能因此认定坏文件被自动修复。</p><p>恢复时先备份覆盖文件，再删除有问题的键或整份覆盖，让默认值生效。不是删除 APK 里的 assets。通过公开配置接口写入可以获得校验和持久化，见<a href="/LyraPlayer-docs-site/plugins/config-schema">schema</a>。</p><p>下一步：<a href="/LyraPlayer-docs-site/config/syntax">语法</a>与<a href="/LyraPlayer-docs-site/config/recipes">常用配方</a>。</p>`,15)])])}const g=s(t,[["render",r]]);export{u as __pageData,g as default};
